sealed trait Shape
final case class Circle(r: Double) extends Shape
final case class Square(side: Double) extends Shape

object Shape {
  def apply(kind: String, size: Double): Shape = kind match {
    case "circle" => Circle(size)
    case "square" => Square(size)
    case other    => throw new IllegalArgumentException(other)
  }
}

val s: Shape = Shape("circle", 1.0)      // sugar for Shape.apply(...)
